import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long lo = nextLong(), hi = nextLong();
        long answer = 0;
        int start = 0, lastMin = -1, lastMax = -1;
        for (int i = 0; i < n; i++) {
            long x = nextLong();
            if (x < lo || x > hi) {
                // Out-of-range value: no valid window may cross it.
                start = i + 1;
                lastMin = lastMax = -1;
                continue;
            }
            if (x == lo) lastMin = i;
            if (x == hi) lastMax = i;
            if (lastMin >= start && lastMax >= start) answer += Math.min(lastMin, lastMax) - start + 1;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	lo, hi := nextInt(), nextInt()
	var answer int64
	start, lastMin, lastMax := 0, -1, -1
	for i := 0; i < n; i++ {
		x := nextInt()
		if x < lo || x > hi {
			// Out-of-range value: no valid window may cross it.
			start = i + 1
			lastMin, lastMax = -1, -1
			continue
		}
		if x == lo {
			lastMin = i
		}
		if x == hi {
			lastMax = i
		}
		if lastMin >= start && lastMax >= start {
			answer += int64(min(lastMin, lastMax) - start + 1)
		}
	}
	fmt.Println(answer)
}
